<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Shared\Security;

use InvalidArgumentException;
use Civi\Lughauth\Shared\AppConfig;

/**
 * ReversibleSecretStorage backed by a local key ring and AES-256-GCM.
 *
 * - Each key has an id; the id travels on the sealed value ("sealed:<key-id>:<payload>").
 * - New values are always sealed with the current key; old keys are kept only to open (and reseal).
 * - The AES key is derived from each configured secret with HKDF-SHA256 (no per-message PBKDF2).
 * - The context is used as GCM additional authenticated data.
 *
 * Configuration (env or application.yaml):
 * - security.secrets.keys / SECURITY_SECRETS_KEYS: "k2:<secret>,k1:<old-secret>" (secrets without commas, ideally 32 random bytes in base64).
 * - security.secrets.current / SECURITY_SECRETS_CURRENT: id of the key used to seal (default: the first one).
 */
class KeyRingSecretStorage implements ReversibleSecretStorage
{
    private const string ALGO = 'aes-256-gcm';
    private const int IV_LENGTH = 12;
    private const int TAG_LENGTH = 16;
    private const string HKDF_INFO = 'lughauth/reversible-secret-storage/';
    /**
     * Generic key used while no key ring is configured. Not suitable for production.
     */
    public const string DEFAULT_KEY_ID = 'k0';
    public const string DEFAULT_SECRET = 'clave-cifrado';

    /**
     * @var array<string, string> derived AES keys by key id.
     */
    private readonly array $keys;

    /**
     * @param array<string, string> $secrets Secrets by key id.
     * @param string $currentKeyId Key used to seal new values.
     */
    public function __construct(
        array $secrets,
        private readonly string $currentKeyId
    ) {
        if (!isset($secrets[$currentKeyId])) {
            throw new InvalidArgumentException('The current key ' . $currentKeyId . ' is not on the key ring');
        }
        $keys = [];
        foreach ($secrets as $id => $secret) {
            if (!preg_match('/^[a-zA-Z0-9_-]{1,32}$/', (string) $id) || '' === $secret) {
                throw new InvalidArgumentException('Invalid key ring entry ' . $id);
            }
            $keys[(string) $id] = hash_hkdf('sha256', $secret, 32, self::HKDF_INFO . $id);
        }
        $this->keys = $keys;
    }

    public static function fromConfig(AppConfig $config): self
    {
        $secrets = [];
        foreach (explode(',', (string) $config->get('security.secrets.keys', '')) as $entry) {
            $parts = explode(':', trim($entry), 2);
            if (2 === count($parts) && '' !== $parts[0] && '' !== $parts[1]) {
                $secrets[$parts[0]] = $parts[1];
            }
        }
        if (!$secrets) {
            $secrets = [self::DEFAULT_KEY_ID => self::DEFAULT_SECRET];
        }
        $current = (string) $config->get('security.secrets.current', array_key_first($secrets));
        return new self($secrets, $current);
    }

    /**
     * True while the generic key is the one used to seal: startup checks can warn or fail on it.
     */
    public function usesDefaultKey(): bool
    {
        return self::DEFAULT_KEY_ID === $this->currentKeyId
            && hash_equals($this->keys[$this->currentKeyId], hash_hkdf('sha256', self::DEFAULT_SECRET, 32, self::HKDF_INFO . self::DEFAULT_KEY_ID));
    }

    #[\Override]
    public function seal(string $plain, string $context): string
    {
        $iv = random_bytes(self::IV_LENGTH);
        $tag = '';
        $cipher = openssl_encrypt($plain, self::ALGO, $this->keys[$this->currentKeyId], OPENSSL_RAW_DATA, $iv, $tag, $context, self::TAG_LENGTH);
        if (false === $cipher) {
            throw new \RuntimeException('Unable to seal the secret');
        }
        return self::SEALED_PREFIX . $this->currentKeyId . ':' . self::base64UrlEncode($iv . $cipher . $tag);
    }

    #[\Override]
    public function open(string $sealed, string $context): string
    {
        [$keyId, $payload] = $this->parse($sealed);
        $raw = self::base64UrlDecode($payload);
        if (null === $raw || strlen($raw) < self::IV_LENGTH + self::TAG_LENGTH) {
            throw new InvalidArgumentException('Malformed sealed secret');
        }
        $iv = substr($raw, 0, self::IV_LENGTH);
        $tag = substr($raw, -self::TAG_LENGTH);
        $cipher = substr($raw, self::IV_LENGTH, -self::TAG_LENGTH);
        $plain = openssl_decrypt($cipher, self::ALGO, $this->keys[$keyId], OPENSSL_RAW_DATA, $iv, $tag, $context);
        if (false === $plain) {
            throw new InvalidArgumentException('Unable to open the sealed secret');
        }
        return $plain;
    }

    #[\Override]
    public function needsReseal(string $sealed): bool
    {
        return $this->parse($sealed)[0] !== $this->currentKeyId;
    }

    /**
     * @return array{0: string, 1: string}
     */
    private function parse(string $sealed): array
    {
        if (!str_starts_with($sealed, self::SEALED_PREFIX)) {
            throw new InvalidArgumentException('Not a sealed secret');
        }
        $parts = explode(':', substr($sealed, strlen(self::SEALED_PREFIX)), 2);
        if (2 !== count($parts) || !isset($this->keys[$parts[0]])) {
            throw new InvalidArgumentException('Unknown key for the sealed secret');
        }
        return [$parts[0], $parts[1]];
    }

    private static function base64UrlEncode(string $value): string
    {
        return rtrim(strtr(base64_encode($value), '+/', '-_'), '=');
    }

    private static function base64UrlDecode(string $value): ?string
    {
        $decoded = base64_decode(strtr($value, '-_', '+/'), true);
        return false === $decoded ? null : $decoded;
    }
}
